# -*- coding: utf-8 -*-
"""أدوات الموظف: رواتب، تفاوض، تقارير، مسار مهني، رفاهية، تخطيط يوم."""
from biz_tools import F, S, add, CATS, T
CATS['career'] = ('🧑‍💼', 'أدوات الموظف', 'راتب صافٍ وعرض وظيفي وتفاوض وتقارير وخطة 30-60-90 وإنجازاتك وتخطيط يومك.')

add('net-salary-estimator', 'career', '💵', 'حاسبة الراتب الصافي', 'من الراتب الأساسي والبدلات إلى الصافي بعد الاستقطاعات.',
 [F('b', 'الراتب الأساسي', 'n', 8000), F('h', 'بدل السكن', 'n', 2000), F('o', 'بدلات أخرى (نقل…)', 'n', 800), F('p', 'نسبة التأمينات على (الأساسي+السكن) %', 'n', 9.75, h='عدّلها حسب بلدك'), F('x', 'استقطاعات أخرى', 'n', 0)],
 r'''function compute(v){const g=v.b+v.h+v.o,ins=(v.b+v.h)*v.p/100,net=g-ins-v.x;return kpis([kpi('إجمالي الراتب',f(g)),kpi('التأمينات',f(ins),'bad'),kpi('الصافي الشهري',f(net),'good'),kpi('الصافي السنوي',f(net*12))])+rec([net/g<0.88?'نسبة الاستقطاع مرتفعة؛ راجع بنود الخصم في مسير الرواتب.':'استقطاعاتك ضمن المعتاد.','وزّع الصافي: 50% احتياجات، 30% التزامات، 20% ادخار واستثمار.','ادخر 3 إلى 6 أشهر من الصافي ('+f(net*3,0)+' إلى '+f(net*6,0)+') كصندوق طوارئ.'])+note('النسب تختلف بحسب البلد والنظام. راجع مسير الرواتب والجهة المختصة.')}''')

add('overtime-pay', 'career', '⏰', 'حاسبة العمل الإضافي', 'أجر الساعة وقيمة الساعات الإضافية.',
 [F('s', 'الراتب الأساسي الشهري', 'n', 6000), F('d', 'أيام العمل في الشهر', 'n', 26), F('hr', 'ساعات العمل اليومية', 'n', 8), F('ot', 'ساعات إضافية في الشهر', 'n', 20), F('m', 'معامل الأجر الإضافي', 'n', 1.5, h='1.5 غالبًا في نظام العمل السعودي: +50%')],
 r'''function compute(v){const rate=v.s/(v.d*v.hr),pay=rate*v.m*v.ot;return kpis([kpi('أجر الساعة',f(rate)),kpi('أجر الساعة الإضافية',f(rate*v.m)),kpi('قيمة الإضافي',f(pay),'good'),kpi('إجمالي الشهر',f(v.s+pay))])+rec([v.ot>40?'ساعاتك الإضافية كثيرة؛ تأكد من الحد النظامي وراحتك.':'ساعاتك الإضافية ضمن المعقول.','وثّق ساعاتك الإضافية يوميًا واطلب اعتمادها كتابيًا.','ادخر جزءًا من الأجر الإضافي بدل اعتباره دخلًا ثابتًا.'])+note('تأكد من نظام العمل وعقدك.')}''')

add('true-hourly-wage', 'career', '🕰️', 'أجر الساعة الحقيقي', 'احسب ما تكسبه فعلًا بعد المواصلات والوقت والتكاليف.',
 [F('s', 'صافي الراتب الشهري', 'n', 9000), F('h', 'ساعات العمل الأسبوعية', 'n', 45), F('c', 'وقت المواصلات يوميًا (دقيقة)', 'n', 80), F('d', 'أيام العمل أسبوعيًا', 'n', 5), F('k', 'تكاليف العمل الشهرية (مواصلات، وجبات…)', 'n', 900)],
 r'''function compute(v){const wk=4.33,hrs=(v.h+v.c*v.d/60)*wk,nom=v.s/(v.h*wk),real=(v.s-v.k)/hrs;return kpis([kpi('أجر الساعة الاسمي',f(nom)),kpi('الأجر الحقيقي',f(real),'good'),kpi('الفرق',f((1-real/nom)*100,0)+'%','bad'),kpi('ساعات حياتك المرتبطة بالعمل/شهر',f(hrs,0))])+rec([real/nom<0.85?'الأجر الحقيقي أقل بكثير من الاسمي: فاوض على العمل عن بعد أو بدل مواصلات.':'الفرق بين الأجرين مقبول.','قبل قبول وظيفة جديدة احسب هذا الرقم لها أيضًا.','ساعة مواصلات يوميًا تعادل نحو 5 أسابيع عمل في السنة.'])+note('وقتك أغلى مما يظهر في العقد: ادخل المواصلات والتكاليف في قرار قبول الوظائف.')}''')

add('raise-calculator', 'career', '📈', 'حاسبة العلاوة والتضخم', 'هل علاوتك تتفوق فعلًا على التضخم؟',
 [F('c', 'راتبك الحالي', 'n', 9000), F('r', 'نسبة العلاوة %', 'n', 5), F('i', 'التضخم السنوي %', 'n', 2.5), F('t', 'الراتب المستهدف', 'n', 12000)],
 r'''function compute(v){const n=v.c*(1+v.r/100),real=(1+v.r/100)/(1+v.i/100)-1;let y=0,s=v.c;while(s<v.t&&y<40){s*=1+v.r/100;y++}return kpis([kpi('الراتب الجديد',f(n),'good'),kpi('الزيادة الشهرية',f(n-v.c)),kpi('الزيادة الحقيقية',f(real*100,2)+'%',real<0?'bad':'good'),kpi('سنوات للوصول للهدف بهذه الوتيرة',y>=40?'+40':y)])+rec([real<0?'علاوتك أقل من التضخم: الراتب الحقيقي يتراجع.':'علاوتك تتفوق على التضخم.',y>5?'للوصول لهدفك أسرع: غيّر الوظيفة أو اطلب ترقية، فالعلاوة السنوية وحدها بطيئة.':'وتيرتك مقبولة.','ادعم طلبك بأرقام إنجازاتك وبيانات السوق.'])}''')

add('job-offer-comparator', 'career', '⚖️', 'مقارنة عرضين وظيفيين', 'قارن العرضين بالمجموع السنوي وأجر الساعة وجودة الحياة.',
 [F('a1', 'عرض A: الراتب الشهري', 'n', 10000), F('b1', 'A: مكافأة سنوية', 'n', 10000), F('h1', 'A: ساعات أسبوعيًا', 'n', 45), F('l1', 'A: أيام إجازة سنويًا', 'n', 21), F('c1', 'A: تكلفة المواصلات شهريًا', 'n', 800),
  F('a2', 'عرض B: الراتب الشهري', 'n', 9000), F('b2', 'B: مكافأة سنوية', 'n', 18000), F('h2', 'B: ساعات أسبوعيًا', 'n', 40), F('l2', 'B: أيام إجازة سنويًا', 'n', 30), F('c2', 'B: تكلفة المواصلات شهريًا', 'n', 300)],
 r'''function compute(v){const t=(a,b,h,l,c)=>{const y=a*12+b-c*12;const hrs=h*52-(l/5)*h;return{y:y,hr:y/hrs}};const A=t(v.a1,v.b1,v.h1,v.l1,v.c1),B=t(v.a2,v.b2,v.h2,v.l2,v.c2);const w=A.hr>B.hr?'A':'B';return tbl(['','عرض A','عرض B'],[['الدخل السنوي الصافي من التكاليف',f(A.y),f(B.y)],['أجر الساعة الفعلي',f(A.hr),f(B.hr)],['أيام الإجازة',v.l1,v.l2]])+kpis([kpi('الأفضل ماليًا لكل ساعة','عرض '+w,'good')])+rec(['لا تقرر بالمال فقط: قيّم النمو، المدير، الثقافة، الاستقرار.','اطلب من الجهة الأقل تحسين العرض بناءً على العرض الآخر.','اسأل عن شروط المكافأة: مضمونة أم مرتبطة بالأداء؟'])+note('القرار لا يقتصر على المال: النمو والثقافة والاستقرار والمسافة والمدير.')}''')

add('leave-balance', 'career', '🏖️', 'حاسبة رصيد الإجازة', 'الرصيد المستحق بحسب تاريخ التعيين والمستخدم.',
 [F('s', 'تاريخ المباشرة', 'date', '2024-01-01'), F('e', 'حتى تاريخ', 'date', '2026-11-26'), F('y', 'أيام الإجازة السنوية', 'n', 21), F('u', 'المستخدم منها', 'n', 30)],
 r'''function compute(v){const a=new Date(v.s),b=new Date(v.e);const days=Math.max(0,(b-a)/864e5),acc=days/365*v.y;return kpis([kpi('مدة الخدمة',f(days/365,1)+' سنة'),kpi('المستحق',f(acc,1)+' يوم'),kpi('المتبقي',f(acc-v.u,1)+' يوم',acc-v.u<0?'bad':'good')])+rec([acc-v.u>15?'لديك رصيد كبير؛ خذ إجازة قبل ضياعه أو تراكمه.':'','خطط لإجازاتك مبكرًا لتنسيق التسليم.','الإجازة تحمي الإنتاجية والصحة.'])+note('بعض الأنظمة تزيد الإجازة بعد سنوات الخدمة. راجع سياستك.')}''')

add('work-day-planner', 'career', '🗓️', 'مخطط يوم العمل (جدول تلقائي)', 'أدخل مهامك بالدقائق والأولوية فيرتبها في جدول مع استراحات.',
 [F('st', 'بداية اليوم', 't', '08:00'), F('br', 'استراحة بعد كل (دقيقة)', 'n', 90), F('bl', 'مدة الاستراحة', 'n', 10), F('t', 'المهام (مهمة | دقائق | أولوية 1-3)', 'textarea', 'رد على البريد | 30 | 2\nتقرير المبيعات | 90 | 1\nاجتماع الفريق | 45 | 2\nمتابعة العملاء | 60 | 1\nمهام إدارية | 40 | 3', r=6)],
 r'''function compute(v){let L=lines(v.t).map(r=>({n:r[0],m:num(r[1]||30),p:num(r[2]||2)})).sort((a,b)=>a.p-b.p);const m=s=>{const p=s.split(':');return +p[0]*60+(+p[1]||0)},hh=x=>String(Math.floor(x/60)%24).padStart(2,'0')+':'+String(x%60).padStart(2,'0');let c=m(v.st),run=0,rows=[];L.forEach(x=>{if(run>=v.br){rows.push([hh(c)+' - '+hh(c+v.bl),'☕ استراحة','']);c+=v.bl;run=0}rows.push([hh(c)+' - '+hh(c+x.m),esc(x.n),['','🔴 عالية','🟠 متوسطة','🟢 منخفضة'][x.p]||'']);c+=x.m;run+=x.m});return tbl(['الوقت','المهمة','الأولوية'],rows)+kpis([kpi('ينتهي اليوم',hh(c)),kpi('إجمالي المهام',f(L.reduce((a,x)=>a+x.m,0)/60,1)+' ساعة')])+note('ابدأ بالأولوية الأعلى في وقت طاقتك الأعلى.')}''')

add('weekly-report-generator', 'career', '📋', 'مولّد تقرير الأسبوع للمدير', 'ملاحظات سريعة ← تقرير مرتب جاهز للإرسال.',
 [F('n', 'اسمك', 'text', 'أحمد'), F('d', 'ما أنجزته (سطر لكل بند)', 'textarea', 'أغلقت 12 طلب عميل\nجهزت عرض سعر لشركة النور', r=4), F('p', 'قيد التنفيذ', 'textarea', 'مراجعة عقد المورد', r=3), F('b', 'عوائق أحتاج مساعدة فيها', 'textarea', 'تأخر اعتماد الميزانية', r=2), F('x', 'خطة الأسبوع القادم', 'textarea', 'زيارة 8 عملاء\nإقفال تقرير الشهر', r=3)],
 r'''function compute(v){const L=t=>String(t).split('\n').map(x=>x.trim()).filter(Boolean).map(x=>'- '+x).join('\n');const r='تقرير الأسبوع - '+v.n+'\n\n✅ المنجز:\n'+L(v.d)+'\n\n🔄 قيد التنفيذ:\n'+L(v.p)+'\n\n⚠️ عوائق/دعم مطلوب:\n'+L(v.b)+'\n\n🎯 الأسبوع القادم:\n'+L(v.x);return '<pre class="tpl" id="pr">'+esc(r)+'</pre>'+note('انسخه وأرسله. اجعل أهم إنجاز في السطر الأول وأضف الأرقام.')}''')

add('self-review-writer', 'career', '🪞', 'كاتب التقييم الذاتي للأداء', 'حوّل إنجازاتك إلى تقييم ذاتي مقنع (برومت جاهز).', 
 [F('r', 'وظيفتك', 'text', 'مندوب مبيعات'), F('a', 'إنجازاتك (سطر لكل إنجاز مع الرقم)', 'textarea', 'حققت 112% من الهدف\nأدرت 85 عميلًا\nدرّبت موظفًا جديدًا', r=5), F('c', 'تحديات واجهتها', 'textarea', 'ارتفاع المنافسة', r=2), F('g', 'أهداف العام القادم', 'textarea', 'تطوير مهارات التفاوض', r=2)],
 r'''function compute(v){return aiOut('أنت مدرب مهني. اكتب لي تقييمًا ذاتيًا للأداء لوظيفة '+v.r+' بنبرة واثقة ومتواضعة، في 4 أقسام: الإنجازات (مع الأثر)، التحديات وكيف تعاملت معها، نقاط التطوير، الأهداف القادمة. لا تضخّم ولا تخترع.\n<الإنجازات>\n'+v.a+'\n</الإنجازات>\n<التحديات>'+v.c+'</التحديات>\n<الأهداف>'+v.g+'</الأهداف>')}''', ai=True)

add('promotion-case-builder', 'career', '🏆', 'ملف طلب الترقية', 'ابنِ قضية الترقية بالأدلة والأثر.', 
 [F('r', 'وظيفتك الحالية', 'text', 'محاسب'), F('t', 'المسمى المطلوب', 'text', 'محاسب أول'), F('y', 'مدة بالمنصب (سنة)', 'n', 2), F('a', 'إنجازات بالأرقام', 'textarea', 'خفضت وقت الإقفال 50%\nأدرت فريق من 3', r=4), F('s', 'مهام فوق وظيفتك الحالية', 'textarea', 'أدرب الجدد، وأعد التقرير للمدير', r=3)],
 r'''function compute(v){const doc='طلب ترقية: من '+v.r+' إلى '+v.t+'\n\nالمدة في المنصب: '+v.y+' سنة\n\nالإنجازات:\n'+String(v.a).split('\n').filter(Boolean).map(x=>'- '+x).join('\n')+'\n\nمهام بمستوى المنصب المطلوب:\n'+String(v.s).split('\n').filter(Boolean).map(x=>'- '+x).join('\n')+'\n\nالطلب: مناقشة الترقية في اجتماع خاص.';return '<pre class="tpl" id="pr">'+esc(doc)+'</pre>'+aiOut('أنت مستشار مهني. اكتب مذكرة طلب ترقية من '+v.r+' إلى '+v.t+' في 200 كلمة، مبنية على الأدلة، بنبرة محترمة وواثقة، وتنتهي بطلب اجتماع.\nالإنجازات:\n'+v.a+'\nمهام فوق الوظيفة:\n'+v.s)}''', ai=True)

add('salary-negotiation-script', 'career', '🤝', 'نص التفاوض على الراتب', 'عبارات جاهزة لطلب زيادة أو التفاوض على عرض.', 
 [S('m', 'الموقف', [('raise', 'طلب زيادة من مديري'), ('offer', 'التفاوض على عرض جديد'), ('counter', 'رد على عرض منخفض')]), F('c', 'راتبك/عرضهم الحالي', 'n', 9000), F('t', 'الرقم المستهدف', 'n', 11000), F('e', 'أبرز أدلة قيمتك', 'textarea', 'حققت 112% من الهدف\nعملاء جدد 40', r=3)],
 r'''function compute(v){const lo=Math.round(v.t*1.0),hi=Math.round(v.t*1.1);const S={raise:'أقدّر دعمكم وفرصة العمل معكم. خلال العام الماضي '+String(v.e).split('\n').filter(Boolean).join('، ')+'. بناءً على ذلك ومعايير السوق لمستوى مسؤولياتي، أرغب بمناقشة تعديل راتبي إلى نطاق '+f(lo,0)+' - '+f(hi,0)+'. ما رأيكم؟',offer:'شكرًا على العرض، أنا متحمس للانضمام. بناءً على خبرتي ('+String(v.e).split('\n')[0]+') ومتوسط السوق، أتطلع لراتب في نطاق '+f(lo,0)+' - '+f(hi,0)+'. هل يمكننا الوصول لذلك؟',counter:'أشكركم على العرض. الرقم أقل من توقعاتي. أطلب '+f(lo,0)+'، وإن تعذر فأنا منفتح على حزمة تتضمن مكافأة أو إجازات أو تطويرًا مهنيًا.'};return '<pre class="tpl" id="pr">'+esc(S[v.m])+'</pre>'+kpis([kpi('الزيادة المطلوبة',f((v.t/v.c-1)*100,1)+'%')])+note('ابحث عن متوسط السوق أولًا، واطلب أعلى قليلًا من هدفك، وتفاوض على الحزمة كاملة.')+aiOut('تدرب معي على تفاوض راتب: أنت المدير وأنا الموظف ('+v.m+'). ابدأ بالاعتراض الأشهر ورد على حججي بواقعية، ثم قيّم أدائي.')}''', ai=True)

add('resignation-letter', 'career', '📝', 'مولّد خطاب الاستقالة', 'خطاب استقالة مهني بنبرات مختلفة.', 
 [F('n', 'اسمك', 'text', 'أحمد محمد'), F('p', 'المسمى', 'text', 'مندوب مبيعات'), F('c', 'الشركة', 'text', 'شركة الأفق'), F('d', 'آخر يوم عمل', 'date', '2026-12-31'), S('t', 'النبرة', [('0', 'رسمية'), ('1', 'ودية شاكرة'), ('2', 'مختصرة')])],
 r'''function compute(v){const T=['السادة/ '+v.c+' المحترمين\n\nأتقدم بطلب استقالتي من وظيفة '+v.p+' اعتبارًا من تاريخ '+v.d+' وفق فترة الإشعار.\n\nأشكر الإدارة وزملائي، وسأعمل على تسليم مهامي بشكل منظم.\n\nمع التقدير،\n'+v.n,'عزيزي المدير،\n\nبعد تفكير، قررت الاستقالة من منصب '+v.p+' وآخر يوم عمل لي '+v.d+'. أنا ممتن للفرصة وللدعم والخبرة التي اكتسبتها في '+v.c+'. سأبذل جهدي لتسهيل الانتقال وتسليم المهام.\n\nمع الشكر،\n'+v.n,'أتقدم باستقالتي من وظيفة '+v.p+' وآخر يوم عمل '+v.d+'.\n'+v.n];return '<pre class="tpl" id="pr">'+esc(T[+v.t])+'</pre>'+note('راجع عقدك وفترة الإشعار، وسلّم الخطاب رسميًا واحتفظ بنسخة.')}''')

add('plan-30-60-90', 'career', '🚀', 'خطة 30-60-90 يومًا للوظيفة الجديدة', 'خطة أول 90 يومًا لتترك انطباعًا قويًا.', 
 [F('r', 'الوظيفة', 'text', 'مدير مبيعات'), F('g', 'أهم هدف للدور', 'text', 'زيادة المبيعات 20%'), F('s', 'تحدي الفريق/الشركة', 'text', 'ضعف المتابعة')],
 r'''function compute(v){const s=[['أول 30 يومًا: تعلّم','- قابل المدير والفريق وأصحاب المصلحة.\n- افهم منتجات الشركة وعملاءها وأرقامها.\n- اجمع 3 مكاسب سريعة محتملة حول: '+v.s],['31-60: ساهم','- نفذ مكسبين سريعين.\n- حدد خطة لتحقيق: '+v.g+'.\n- اطلب ملاحظات أسبوعية من مديرك.'],['61-90: قُد','- قدّم نتائج ملموسة ومؤشرات متابعة.\n- اعرض خطة 6 أشهر.\n- وثّق ما تعلمته وما تغيّر.']];return s.map(x=>'<div class="chk ok"><b>'+x[0]+'</b><pre class="tpl">'+esc(x[1])+'</pre></div>').join('')+aiOut('ضع خطة 30-60-90 يومًا مفصلة لوظيفة '+v.r+'، الهدف: '+v.g+'، التحدي: '+v.s+'. اعرضها بجدول: الفترة، الإجراءات، المخرج، مؤشر النجاح.')}''', ai=True)

add('one-on-one-agenda', 'career', '🗣️', 'جدول اجتماع 1:1 مع المدير', 'اجعل اجتماعك مع مديرك منتجًا.', 
 [F('w', 'ما حدث منذ آخر لقاء', 'textarea', 'أنجزت تقرير الربع', r=2), F('b', 'عوائق', 'textarea', 'ننتظر موافقة الميزانية', r=2), F('f', 'ملاحظات تريدها', 'textarea', 'كيف أتطور في التفاوض؟', r=2), F('c', 'طلب/قرار تحتاجه', 'text', 'موافقة على تدريب')],
 r'''function compute(v){const a='جدول اجتماع 1:1 (30 دقيقة)\n\n1) تحديث سريع (5د): '+v.w+'\n2) عوائق (7د): '+v.b+'\n3) ملاحظات وتطوير (10د): '+v.f+'\n4) قرار/طلب (5د): '+v.c+'\n5) الاتفاق على الخطوات (3د)';return '<pre class="tpl" id="pr">'+esc(a)+'</pre>'+note('أرسله قبل اللقاء بيوم، ودوّن القرارات بعده.')}''')

add('brag-document', 'career', '📓', 'ملف الإنجازات (Brag Document)', 'سجّل إنجازاتك أولًا بأول لتقييمك وسيرتك.', 
 [F('t', 'إنجازات (تاريخ | الإنجاز | الأثر)', 'textarea', '2026-03 | أطلقت قالب رد جديد | خفض وقت الرد 25%\n2026-06 | درّبت 3 موظفين | رفع سرعة التعيين\n2026-09 | أغلقت عقد 400 ألف | 15% من الهدف', r=8)],
 r'''function compute(v){const L=lines(v.t);if(!L.length)return'';const rows=L.map(r=>[r[0]||'',esc(r[1]||''),esc(r[2]||'')]);return tbl(['التاريخ','الإنجاز','الأثر'],rows)+kpis([kpi('عدد الإنجازات',L.length)])+aiOut('حوّل إنجازاتي إلى 5 نقاط قوية لسيرتي الذاتية بصيغة فعل + إنجاز + رقم + أثر، وإلى فقرة تقييم ذاتي:\n'+v.t)+note('خزّن ملفك محليًا وحدّثه أسبوعيًا؛ هذه مادة سيرتك وتقييمك وطلب الترقية.')}''', ai=True)

add('skill-gap-analyzer', 'career', '🧭', 'محلل فجوة المهارات', 'قارن مهاراتك بمتطلبات الوظيفة المستهدفة وخطط للتعلّم.', 
 [F('c', 'مهاراتك الحالية (مهارة | مستوى 1-5)', 'textarea', 'Excel | 4\nالتفاوض | 3\nCRM | 2\nتحليل البيانات | 2', r=5), F('t', 'المطلوب للوظيفة (مهارة | مستوى مطلوب)', 'textarea', 'Excel | 4\nالتفاوض | 4\nCRM | 4\nتحليل البيانات | 4\nPower BI | 3', r=5)],
 r'''function compute(v){const C={};lines(v.c).forEach(r=>C[AR2(r[0])]=num(r[1]||0));const rows=lines(v.t).map(r=>{const k=AR2(r[0]),need=num(r[1]||3),have=C[k]||0,g=need-have;return{n:r[0],have:have,need:need,g:g}}).sort((a,b)=>b.g-a.g);return tbl(['المهارة','لديك','المطلوب','الفجوة'],rows.map(r=>[esc(r.n),r.have,r.need,r.g>0?'<b style="color:#dc2626">'+r.g+'</b>':'✅'])).replace(/AR2/g,'')+kpis([kpi('مهارات بفجوة',rows.filter(r=>r.g>0).length,'bad'),kpi('جاهزيتك',f(100*rows.filter(r=>r.g<=0).length/Math.max(1,rows.length),0)+'%','good')])+aiOut('أنا أريد الانتقال لوظيفة تتطلب هذه المهارات. فجواتي: '+rows.filter(r=>r.g>0).map(r=>r.n+' (لدي '+r.have+' من '+r.need+')').join('، ')+'. ضع خطة تعلم 12 أسبوعًا مع موارد مجانية ومشروع تطبيقي لكل مهارة.')}
function AR2(s){return String(s).trim().toLowerCase()}''', ai=True)

add('burnout-self-check', 'career', '🔋', 'مقياس الإجهاد المهني (تأمل ذاتي)', 'أسئلة تأملية لتقدير مستوى ضغط العمل (ليست تشخيصًا طبيًا).', 
 [S('q1', 'أشعر بالإرهاق قبل بدء يوم العمل', [('0', 'نادرًا'), ('1', 'أحيانًا'), ('2', 'غالبًا'), ('3', 'دائمًا')]), S('q2', 'أجد صعوبة في الفصل عن العمل بعد الدوام', [('0', 'نادرًا'), ('1', 'أحيانًا'), ('2', 'غالبًا'), ('3', 'دائمًا')]), S('q3', 'فقدت الحماس تجاه مهامي', [('0', 'نادرًا'), ('1', 'أحيانًا'), ('2', 'غالبًا'), ('3', 'دائمًا')]), S('q4', 'أشعر أن عبء العمل أكبر من طاقتي', [('0', 'نادرًا'), ('1', 'أحيانًا'), ('2', 'غالبًا'), ('3', 'دائمًا')]), S('q5', 'أنام وأنا أفكر في العمل', [('0', 'نادرًا'), ('1', 'أحيانًا'), ('2', 'غالبًا'), ('3', 'دائمًا')])],
 r'''function compute(v){const s=+v.q1+ +v.q2+ +v.q3+ +v.q4+ +v.q5;const l=s<=4?['منخفض','good','حافظ على توازنك وإجازاتك.']:s<=9?['متوسط','','راجع أولوياتك، خذ استراحات منتظمة، وتحدث مع مديرك عن العبء.']:['مرتفع','bad','خذ الأمر بجدية: حدّ العبء، اطلب دعمًا، وتحدث مع مختص إن استمر الشعور.'];return kpis([kpi('درجتك من 15',s),kpi('مستوى الضغط',l[0],l[1])])+'<p>'+l[2]+'</p>'+note('هذه أداة تأمل ذاتي وليست تشخيصًا. عند تأثر صحتك أو نومك استشر مختصًا.')}''')

add('career-goal-roadmap', 'career', '🎯', 'خارطة الهدف المهني SMART', 'حوّل طموحك إلى خطة بخطوات وتواريخ.', 
 [F('g', 'هدفك المهني', 'text', 'أصبح مدير مبيعات خلال 3 سنوات'), F('y', 'المدة (أشهر)', 'n', 36), F('s', 'مهارات ستتعلمها', 'textarea', 'القيادة\nتحليل المبيعات\nإدارة الميزانية', r=3), F('m', 'مقياس النجاح', 'text', 'ترقية + قيادة فريق 5')],
 r'''function compute(v){const L=String(v.s).split('\n').filter(Boolean),n=Math.max(1,L.length),per=v.y/(n+1);let rows=L.map((x,i)=>['الشهر '+Math.round(per*(i+1)),esc(x)]);rows.push(['الشهر '+v.y,'تحقيق الهدف: '+esc(v.m)]);return '<div class="chk ok"><b>الهدف:</b> '+esc(v.g)+'<br><small>محدد ✅ قابل للقياس: '+esc(v.m)+' · زمني: '+v.y+' شهرًا</small></div>'+tbl(['متى','المحطة'],rows)+aiOut('ضع لي خطة تحقيق الهدف المهني: '+v.g+' خلال '+v.y+' شهرًا. المهارات: '+L.join('، ')+'. لكل ربع سنة: أهداف، إجراءات، مؤشر قياس، مخاطر.')}''', ai=True)

add('work-email-templates', 'career', '✉️', 'قوالب رسائل العمل الجاهزة', '14 قالب بريد لمواقف العمل اليومية.', 
 [S('k', 'الموقف', [('leave', 'طلب إجازة'), ('raise', 'طلب اجتماع لمناقشة الراتب'), ('follow', 'متابعة بعد اجتماع'), ('late', 'اعتذار عن تأخير'), ('help', 'طلب مساعدة من زميل'), ('decline', 'الاعتذار عن مهمة إضافية'), ('thanks', 'شكر زميل'), ('feedback', 'طلب ملاحظات على أدائي'), ('remote', 'طلب عمل عن بعد'), ('training', 'طلب دورة تدريبية'), ('report', 'تسليم تقرير'), ('intro', 'تعريف بنفسك لفريق جديد'), ('deadline', 'تمديد موعد تسليم'), ('ooo', 'رد غياب تلقائي')]), F('n', 'اسم المستلم', 'text', 'أستاذ خالد'), F('d', 'تفصيل (تاريخ/موضوع)', 'text', 'من 5 إلى 9 ديسمبر')],
 r'''function compute(v){const n=v.n,d=v.d;const M={leave:['طلب إجازة','أرجو التكرم بالموافقة على إجازتي '+d+'. سأنجز مهامي العاجلة قبلها وأسلّم المتابعة لزميلي.'],raise:['طلب اجتماع','أرغب بتحديد موعد قصير لمناقشة تطوري المهني ومراجعة راتبي. أجهّز ملخصًا لإنجازاتي: '+d],follow:['متابعة اجتماع','شكرًا على الاجتماع. ملخص ما اتفقنا عليه: '+d+'. سأنفذ ما يخصني وأوافيكم بالتحديث.'],late:['اعتذار عن التأخير','أعتذر عن التأخر في '+d+'. سأنجزه خلال [الموعد] وأعدكم بتجنب تكراره.'],help:['طلب مساعدة','أحتاج دعمك في '+d+'. هل يمكننا 15 دقيقة اليوم؟ سأجهّز ما لدي مسبقًا.'],decline:['الاعتذار عن مهمة','أقدّر ثقتك. حاليًا أنا ملتزم بـ[مهامي] ولا أستطيع تنفيذ '+d+' بالجودة المطلوبة. هل نعيد ترتيب الأولويات أو نحدد موعدًا لاحقًا؟'],thanks:['شكر','شكرًا على مساعدتك في '+d+'. كان لها أثر حقيقي في إنجاز العمل.'],feedback:['طلب ملاحظات','أود تحسين أدائي. هل لديك ملاحظات على '+d+' وما الذي يمكنني فعله بشكل أفضل؟'],remote:['طلب عمل عن بعد','أرغب بطلب العمل عن بعد '+d+'. سأحافظ على التواصل والتسليم في المواعيد ويمكنني تقديم خطة متابعة.'],training:['طلب تدريب','أرغب بالتسجيل في دورة '+d+' لأنها ترفع جودة عملي وتخدم أهداف الفريق. التكلفة والمدة مرفقة.'],report:['تسليم تقرير','مرفق تقرير '+d+'. أبرز النتائج في الصفحة الأولى، وأنا جاهز لأي استفسار.'],intro:['تعريف بالنفس','أنا '+d+' وانضممت للفريق. أتطلع للتعاون معكم، وسأكون ممتنًا لأي نصيحة تساعدني على الاندماج بسرعة.'],deadline:['تمديد موعد','لتسليم '+d+' بجودة أفضل أطلب تمديد الموعد إلى [التاريخ]. ما أنجزته حتى الآن: [..].'],ooo:['رد غياب','أنا خارج المكتب '+d+' وسأرد عند عودتي. للأمور العاجلة تواصلوا مع [الاسم].']}[v.k];return '<pre class="tpl" id="pr">'+esc('الموضوع: '+M[0]+'\n\nالأستاذ/ة '+n+'، تحية طيبة\n\n'+M[1]+'\n\nمع خالص التقدير')+'</pre>'+note('عدّل الأقواس المربعة قبل الإرسال.')}''')

add('meeting-prep-brief', 'career', '📅', 'ملخص تحضير الاجتماع', 'جهّز هدفك وأسئلتك وقرارك قبل أي اجتماع.', 
 [F('t', 'موضوع الاجتماع', 'text', 'مراجعة أداء الربع'), F('g', 'ماذا تريد أن تخرج به؟', 'text', 'موافقة على ميزانية إضافية'), F('p', 'الحاضرون', 'text', 'المدير، المالية'), F('r', 'مخاطر أو اعتراضات متوقعة', 'textarea', 'التكلفة', r=2)],
 r'''function compute(v){return '<pre class="tpl" id="pr">'+esc('اجتماع: '+v.t+'\nالحاضرون: '+v.p+'\nالنتيجة المطلوبة: '+v.g+'\nالاعتراضات المتوقعة: '+v.r+'\n\nقبل الاجتماع:\n- جهز رقمين يدعمان طلبك\n- جهز رد على كل اعتراض\n- جهز سؤالًا واحدًا قويًا\nبعد الاجتماع: أرسل ملخصًا بالقرارات والمهام خلال ساعة')+'</pre>'+aiOut('ساعدني أتحضر لاجتماع: '+v.t+'. الهدف: '+v.g+'. الحضور: '+v.p+'. الاعتراضات: '+v.r+'. اقترح افتتاحية 30 ثانية، 3 نقاط قوية، وردود على الاعتراضات.')}''', ai=True)

