add('elevator-pitch-generator', 'career', '🛗', 'مولّد التعريف بالنفس (Elevator Pitch)', 'تعريف مقنع بنفسك في 30 ثانية للمقابلات والنتورك.',
 [F('n', 'اسمك', 'text', 'أحمد'), F('r', 'وظيفتك', 'text', 'مندوب مبيعات'), F('y', 'سنوات الخبرة', 'n', 4), F('v', 'ما تقدمه من قيمة', 'text', 'أساعد الشركات الصغيرة على زيادة مبيعاتها'), F('a', 'إنجاز بالأرقام', 'text', 'حققت 112% من الهدف'), F('g', 'ما تبحث عنه', 'text', 'فرصة لقيادة فريق مبيعات')],
 r'''function compute(v){const a='مرحبًا، أنا '+v.n+'، '+v.r+' بخبرة '+v.y+' سنوات. '+v.v+'. من إنجازاتي: '+v.a+'. أبحث الآن عن '+v.g+'.';const b='أنا '+v.n+'. '+v.v+'، وأعمل في '+v.r+' منذ '+v.y+' سنوات. آخر نتيجة: '+v.a+'. يهمني '+v.g+'، ما الذي تعملون عليه حاليًا؟';return '<h4>نسخة رسمية</h4><pre class="tpl">'+esc(a)+'</pre><h4>نسخة حوارية</h4><pre class="tpl">'+esc(b)+'</pre>'+rec(['تدرب عليه بصوت عالٍ ليكون في 30 ثانية (نحو 80 كلمة).','ابدأ بالقيمة لا بالمسمى.','أنهِ بسؤال يفتح حوارًا.'])+aiOut('أعد صياغة هذا التعريف بنفسي ليكون طبيعيًا ومقنعًا في 30 ثانية بثلاث نبرات:\n'+a)}''', ai=True)

add('interview-thank-you', 'career', '🙏', 'مولّد رسالة الشكر بعد المقابلة', 'رسالة متابعة تعزز فرصتك بعد المقابلة.',
 [F('n', 'اسمك', 'text', 'أحمد'), F('m', 'اسم المُقابِل', 'text', 'أستاذ خالد'), F('j', 'الوظيفة', 'text', 'مندوب مبيعات'), F('t', 'نقطة ناقشتموها', 'text', 'خطة التوسع في المنطقة الوسطى'), F('c', 'ما تضيفه', 'text', 'تجربتي في فتح 40 حسابًا جديدًا')],
 r'''function compute(v){const m='الموضوع: شكرًا على وقتكم - '+v.j+'\n\nالأستاذ/ة '+v.m+'، تحية طيبة\n\nأشكركم على المقابلة اليوم. استمتعت بالحديث عن '+v.t+'، وزاد حماسي للوظيفة. أعتقد أن '+v.c+' يخدم احتياجكم.\n\nيسعدني تزويدكم بأي معلومات إضافية، وأتطلع لخطواتكم القادمة.\n\nمع التقدير،\n'+v.n;return '<pre class="tpl" id="pr">'+esc(m)+'</pre>'+rec(['أرسلها خلال 24 ساعة.','اذكر نقطة محددة من المقابلة لتبدو مخصصة.','أبقِها أقل من 120 كلمة.'])}''')

add('reference-request', 'career', '🧾', 'طلب خطاب توصية أو مرجع', 'رسالة مهذبة لطلب توصية من مدير أو زميل.',
 [F('n', 'اسمك', 'text', 'أحمد'), F('m', 'اسم من تطلب منه', 'text', 'أستاذ سعد'), F('p', 'عملتما معًا في', 'text', 'مشروع إطلاق المنتج'), F('j', 'الوظيفة المتقدم لها', 'text', 'مدير مبيعات'), F('d', 'الموعد النهائي', 'text', 'نهاية الشهر')],
 r'''function compute(v){const m='الأستاذ/ة '+v.m+'، تحية طيبة\n\nأتمنى أن تكونوا بخير. أتقدم لوظيفة '+v.j+' وأقدّر لو تفضلتم بكتابة توصية عن عملنا في '+v.p+'. يمكنني تزويدكم بملخص لإنجازاتنا وسيرتي لتسهيل الأمر. الموعد المناسب '+v.d+'، وإن لم يتيسر ذلك فأتفهم تمامًا.\n\nشكرًا لدعمكم دائمًا،\n'+v.n;return '<pre class="tpl" id="pr">'+esc(m)+'</pre>'+rec(['اطلب من شخص يعرف عملك جيدًا.','أعطه ملخصًا بنقاط يذكرها.','اشكره بعد الكتابة.'])}''')

add('employee-okr-generator', 'career', '🎯', 'مولّد أهداف الموظف (OKR)', 'أهداف ونتائج رئيسية لوظيفتك ربعًا بربع.',
 [F('r', 'وظيفتك', 'text', 'مندوب مبيعات'), F('o', 'الهدف الأكبر هذا الربع', 'text', 'رفع مبيعاتي'), F('m', 'مؤشر رقمي (قيمة حالية → المستهدفة)', 'text', 'المبيعات 100 ألف → 130 ألف'), F('k', 'أنشطة تعتقد أنها ستحقق الهدف', 'textarea', 'زيارة 30 عميلًا\nمتابعة العروض المفتوحة', r=3)],
 r'''function compute(v){const A=String(v.k).split('\n').filter(Boolean);return '<pre class="tpl" id="pr">'+esc('الهدف (O): '+v.o+'\n\nالنتائج الرئيسية:\nKR1: '+v.m+'\nKR2: إنجاز '+(A[0]||'النشاط الأول')+' بنسبة 100%\nKR3: '+(A[1]||'مؤشر جودة')+' بمعدل [الرقم]\n\nالمتابعة: كل أسبوع خميس')+'</pre>'+rec(['اجعل الهدف ملهمًا والنتائج قابلة للقياس.','3 نتائج رئيسية كافية.','راجعها أسبوعيًا مع مديرك.'])+aiOut('أنت مدرب OKR. حسّن أهدافي لوظيفة '+v.r+': الهدف '+v.o+'، المؤشر '+v.m+'، الأنشطة: '+A.join('، ')+'. اكتب 3 نتائج رئيسية قابلة للقياس وخطة أسبوعية.')}''', ai=True)

add('feedback-phrases-generator', 'career', '💬', 'مولّد عبارات الملاحظات والتقدير', 'عبارات جاهزة لتقديم ملاحظات بناءة أو تقدير زميل.',
 [S('k', 'الغرض', [('praise', 'تقدير إنجاز'), ('improve', 'ملاحظة للتحسين'), ('upward', 'ملاحظة للمدير'), ('peer', 'ملاحظة لزميل')]), F('p', 'الشخص', 'text', 'سارة'), F('s', 'الموقف المحدد', 'text', 'عرض الاجتماع أمس'), F('i', 'الأثر', 'text', 'ساعد الفريق على اتخاذ القرار')],
 r'''function compute(v){const M={praise:['أحببت أسلوبك في '+v.s+'. '+v.i+'. شكرًا لك!','عمل ممتاز يا '+v.p+' في '+v.s+'؛ أثره واضح: '+v.i+'.'],improve:['في '+v.s+' لاحظت [الملاحظة]، وأثرها '+v.i+'. ما رأيك لو جربنا [اقتراح] المرة القادمة؟','أقدّر مجهودك في '+v.s+'. أرى فرصة لتحسين [..] لأن '+v.i+'. أنا جاهز لمساعدتك.'],upward:['لدي اقتراح بخصوص '+v.s+': يبدو أن '+v.i+'. هل نستطيع مراجعة [الحل]؟','أود أن أفهم أولويات '+v.s+' لأعمل بشكل أفضل. هل يمكننا الاتفاق على [..]؟'],peer:['أحب العمل معك. بخصوص '+v.s+' أقترح [..] لأن '+v.i+'.','هل يناسبك أن نتفق على طريقة أوضح في '+v.s+'؟ لاحظت أن '+v.i+'.']}[v.k];return M.map(x=>'<pre class="tpl">'+esc(x)+'</pre>').join('')+rec(['اذكر السلوك لا الشخص.','اربط الملاحظة بالأثر.','ختمها باقتراح أو سؤال.'])}''')

add('linkedin-post-generator', 'career', '📣', 'مولّد منشورات لينكدإن للموظف', 'منشور عن إنجاز أو وظيفة جديدة أو درس تعلمته.',
 [S('k', 'النوع', [('win', 'إنجاز مهني'), ('job', 'وظيفة جديدة'), ('lesson', 'درس تعلمته'), ('cert', 'شهادة/دورة')]), F('t', 'الموضوع', 'text', 'تحقيق 112% من هدف المبيعات'), F('l', 'الدرس/الأثر', 'text', 'المتابعة المنتظمة تصنع الفرق'), F('g', 'من تشكر', 'text', 'فريقي ومديري')],
 r'''function compute(v){const M={win:'يسعدني مشاركة إنجاز: '+v.t+'. الدرس الأهم: '+v.l+'. شكرًا لـ'+v.g+' على الدعم. 🙏',job:'خبر سعيد: بدأت مرحلة جديدة! '+v.t+'. أشكر '+v.g+' وأتطلع لما هو قادم.',lesson:'درس تعلمته مؤخرًا: '+v.t+'. الخلاصة: '+v.l+'. ما تجربتكم؟',cert:'أنهيت '+v.t+'. أهم ما تعلمته: '+v.l+'. شكرًا لـ'+v.g+'.'};return '<pre class="tpl" id="pr">'+esc(M[v.k])+'</pre>'+rec(['أضف قصة قصيرة قبل الدرس.','اختم بسؤال للتفاعل.','انشر في وقت ذروة جمهورك (صباح الأسبوع).'])+aiOut('اكتب منشور لينكدإن بنبرة صادقة ومهنية عن: '+v.t+'. الدرس: '+v.l+'. 120 كلمة مع سؤال ختامي بدون مبالغة.')}''', ai=True)

add('status-update-generator', 'career', '📡', 'مولّد تحديث الحالة (Stand-up)', 'تحديث يومي من 3 أسطر للفريق.',
 [F('y', 'أمس أنجزت', 'text', 'أغلقت عرض شركة النور'), F('t', 'اليوم سأعمل على', 'text', 'متابعة 5 عملاء'), F('b', 'عوائق', 'text', 'لا يوجد')],
 r'''function compute(v){return '<pre class="tpl" id="pr">'+esc('تحديث اليوم:\n✅ أمس: '+v.y+'\n🎯 اليوم: '+v.t+'\n🚧 عوائق: '+v.b)+'</pre>'+rec(['اجعله أقل من 30 ثانية.','اذكر العوائق مبكرًا لتُحل بسرعة.'])}''')

add('delegation-message', 'career', '📤', 'مولّد رسالة تكليف/تفويض مهمة', 'كلّف زميلًا أو مرؤوسًا بوضوح.',
 [F('p', 'اسم المكلَّف', 'text', 'سارة'), F('t', 'المهمة', 'text', 'تجهيز تقرير المبيعات الشهري'), F('d', 'الموعد', 'text', 'الخميس 12 ظهرًا'), F('q', 'معيار الجودة', 'text', 'صفحة واحدة بالأرقام والتوصيات'), F('s', 'الدعم المتاح', 'text', 'أستطيع مراجعته غدًا')],
 r'''function compute(v){return '<pre class="tpl" id="pr">'+esc('أهلًا '+v.p+'،\n\nأرجو منك '+v.t+' بحلول '+v.d+'.\nالمطلوب: '+v.q+'.\nالدعم: '+v.s+'.\nأخبرني إن احتجت توضيحًا أو واجهت عائقًا.\n\nشكرًا!')+'</pre>'+rec(['اذكر الهدف والمعيار والموعد.','أعطِ صلاحية كافية.','حدد نقطة متابعة وسطية.'])}''')
